/**
 * The drawing of a ship (its code: Ж, М, И, Г) as an <svg> of the given size; an unknown code — an empty frame. The ids
 * of its gradients are unique to `tag` (one drawing per tag), and the same for the same tag, so React keeps the markup.
 */
const MADE = new Map<string, string>();
export function shipSvg(code: string, width = 58, height = 28, tag = code): string {
  const key = `${code}|${width}|${height}|${tag}`;
  let svg = MADE.get(key);
  if (svg === undefined) {
    svg = `<svg aria-hidden="true" width="${width}" height="${height}" viewBox="-2 -1 124 80">${uidSvg(ART[code] ?? '', 'sh')}</svg>`;
    MADE.set(key, svg);
  }
  return svg;
}
